('لا يوجد أمل.', 'Ümit yok.', 3682),
('إن إرادة الشعب هي مصدر سلطة الحكومة، ويعبر عن هذه الإرادة بانتخابات نزيهة دورية تجري على أساس الاقتراع السري وعلى قدم المساواة بين الجميع، او حسب أي إجراء مماثل يضمن حرية التصويت.', 'Halkın iradesi kamu otoritesinin esasıdır; bu irade, gizli şekilde veya serbestliği sağlayacak muadil bir usul ile cereyan edecek, genel ve eşit oy verme yoluyla yapılacak olan devri ve dürüst seçimlerle ifade edilir.', 3685),
('ليس أنا ، بل أنت!', 'Hayır, ben değilim; sensin!', 3689),
