('متلازمة باريس هي نوع من الصدمة الحضارية. إنه مصطلح نفسي يوصف به الأجانب الذين يبدأون العيش في باريس، مجذوبين إلى صورة المدينة بوصفها مركزًا للموضة، ثم لا يستطيعون الاندماج جيدا مع التقاليد والثقافة المحليين، فيفقدون توازنهم العقلي وتظهر عليهم أعراض قريبة من الاكتئاب.', 'Paris sendromu bir tür kültür şokudur. Şehrin moda merkezi imgesine kapılıp Paris\'te yaşamaya başlayan, sonrasında yerel adetlere ve kültüre iyi uyum sağlayamayıp, zihinsel dengesini yitiren ve depresyona yakın belirtiler gösteren yabancıları tanımlamak için kullanılan psikiyatrik bir terimdir.', 4032),
