('لقد أتيت إلى هنا للبحث عن بداية جديدة بين الولايات المتحدة والعالم الإسلامي استنادا إلى المصلحة المشتركة والاحترام المتبادل وهي بداية مبنية على أساس حقيقة أن أمريكا والإسلام لا تعارضان بعضها البعض ولا داعي أبدا للتنافس فيما بينهما بل ولهما قواسم ومبادئ مشتركة يلتقيان عبرها ألا وهي مبادئ العدالة والتقدم والتسامح وكرامة كل إنسان', 'Ben buraya dünyada Birleşik Devletler ve Müslümanlar arasında yeni bir başlangıç noktası aramak için geldim; biri karşılıklı ilgi ve karşılıklı saygıya dayalı; biri Amerika ve Müslümanın münhasır olmadığı ve rekabet içinde olması gerekmeyen gerçeğine dayalı.Bunun yerine onlar örtüşürler ve ortak prensipleri paylaşırlar - adalet ve ilerleme prensipleri tüm insanların hoşgörü ve haysiyeti.', 47472),
