('عمل كل إنسان، سواءً كان الأدب أو الموسيقى أو الصور أو العِمَارة أو أي شيء آخر، هو دائمًا صورة لنفسه.', 'Her erkeğin işi, ister edebi ya da müzik ya da bir resim ya da mimari ya da başka bir şey olsun, her zaman kendisinin bir portresidir.', 76985),
('إنها الإجابة التي رددها كل صغير وكبير، غني وفقير، ديمقراطي وجمهوري، أسود، أبيض، لاتيني، مواطن أمريكي أصلي، مثلي، عادي، معاق، غير معاق؛ إنهم أمريكيون وجهوا للعالم رسالةً تقول أننا لم نكن أبداً مجرد خليطٍ من ولايات جمهورية وأخرى ديمقراطية: لقد كنا، ولا زلنا، وسنكون الولايات المتحدة الأمريكية.', 'Bu genç ve yaşlı, zengin ve fakir, Demokrat ve Cumhuriyetçi, siyahi, beyaz, Hispanik, Asyalı, Amerikan yerlisi, eşcinsel, düz, engelli ve engelsizler tarafından konuşulan cevaptır. Sadece bir bireyler koleksiyonu veya bir kırmızı ve mavi eyaletler koleksiyonu asla olmadığımızı belirten, dünyaya mesaj gönderenler Amerikalılardır. Biz, ve her zaman Amerika Birleşik Devletleri olacağız.', 77003),
